links=[('overview','敬拜与主旨'),('background','真实背景与全书位置'),('text','经文细读'),('why','一 · 为什么献己'),('how','二 · 怎样献己'),('result','三 · 献己的结果'),('redemption','救赎历史与圣约'),('compare','摩西与基督'),('creeds','三信经阅读与背诵'),('creed-compare','三信经深度对比'),('confessions','三项联合信条'),('memory','快速记忆与自测'),('discussion','详细讨论与答案'),('worship','诗歌与回应'),('sources','资料与版本说明')]
body=section('overview','一位愿意舍己的中保，<br>与那位已经成全的救主', '<div class="ribbon"><span>☀ 下午敬拜</span><span>♫ 圣诗16首</span><span>韵诗29 · 24 · 23篇</span><span>读经 出32:1–35</span><span>证道 出32:30–34</span></div>'+p(C['intro'])+'<blockquote>'+C['thesis']+'</blockquote><div class="note"><b>题目用语说明</b> 本讲保留“摩西作为旧约的中保为以色列百姓的罪代赎”这一题目。“献上自己”指他愿意为民舍己的代求请求；经文没有说摩西成为蒙神悦纳、实际完成赎罪的祭物。</div>', '01 / 从整体进入经文')
body+=section('background','回到西奈：救出来之后，<br>为何又陷入危机？',''.join('<h3>'+a+'</h3>'+p(b) for a,b in C['background'])+'''<figure class="map"><svg viewBox="0 0 900 340" role="img" aria-label="埃及、西奈与迦南的相对位置示意图，非确定出埃及路线"><rect width="900" height="340" rx="20" fill="#e6eef0"/><path d="M0 80L190 80 220 120 220 250 330 340H0Z" fill="#d8c8ac"/><path d="M250 120L385 100 500 270 405 340 350 260Z" fill="#e0d4bc"/><path d="M520 0H900V340H470L550 210 470 95Z" fill="#d8c8ac"/><path d="M160 90Q130 190 170 330" fill="none" stroke="#72a6b1" stroke-width="15"/><text x="50" y="60">地中海</text><text x="65" y="205">埃及</text><text x="300" y="180">西奈地区</text><text x="540" y="75">迦南</text><text x="535" y="270">阿拉伯地区</text><text x="230" y="290" transform="rotate(48 230 290)">苏伊士湾</text><text x="465" y="220" transform="rotate(-38 465 220)">亚喀巴湾</text><circle cx="380" cy="240" r="22" fill="none" stroke="#b77735" stroke-width="2" stroke-dasharray="4 4"/><text x="330" y="310" class="small-svg">西奈山确切位置有争议</text></svg><figcaption>原创区域示意图 · 非比例地图；圆圈仅提示传统讨论区域，不表示已确定的山址。不绘制未经证实的出埃及路线。</figcaption></figure><div class="journey"><div>出1–18<br><b>救离奴役</b></div><i>→</i><div>出19–24<br><b>立约归神</b></div><i>→</i><div>出25–31<br><b>会幕指示</b></div><i>→</i><div class="hot">出32–34<br><b>背约与恢复</b></div><i>→</i><div>出35–40<br><b>荣光同住</b></div></div>''','02 / 历史、文学与地理')
verses=[(30,'到了第二天，摩西对百姓说：你们犯了大罪。我如今要上耶和华那里去，或者可以为你们赎罪。'),(31,'摩西回到耶和华那里，说：唉！这百姓犯了大罪，为自己做了金像。'),(32,'倘或你肯赦免他们的罪……不然，求你从你所写的册上涂抹我的名。'),(33,'耶和华对摩西说：谁得罪我，我就从我的册上涂抹谁的名。'),(34,'现在你去领这百姓，往我所告诉你的地方去，我的使者必在你前面引路；只是到我追讨的日子，我必追讨他们的罪。')]
exegesis=[('30 · 大罪／或者','大罪两次出现，拒绝粉饰；或者显示请求尚未获得保证。赎罪的用语表达摩西寻求除罪、恢复关系，不证明神已认可他的献己。'),('31 · 回到／金像','他向被得罪的神认具体的罪，而不是仅在群体里安抚情绪；与亚伦推责的说法对照。'),('32 · 赦免／涂抹','祈求中的停顿与极深认同；册子涉及生命、归属的意象。本文未直接称之为羔羊的生命册。'),('33 · 谁得罪我','神维护责任，没有接受摩西交换名额。不能把这句扩大为否认神后来亲自设立的基督代赎。'),('34–35 · 引路／追讨','存留与审判同时存在。瘟疫、33章同在危机、34章更新约，共同解释结果，不能只读到获准前行为止。')]
body+=section('text','五节经文，五个转折','<div class="scripture">'+''.join(f'<p><sup>{n}</sup>{v}</p>' for n,v in verses)+'</div><p class="caption">中文和合本；删除原站汉字间显示空格，以段落排版。<a href="https://www.biblegateway.com/passage/?search=Exodus%2032&version=CUVS" target="_blank" rel="noopener">阅读出埃及记32章全文 ↗</a></p><div class="grid two">'+''.join('<article class="small-card"><h3>'+a+'</h3>'+p(b)+'</article>' for a,b in exegesis)+'</div><div class="note">区分三层：<b>经文明说</b>（愿被涂抹、神仍追讨）；<b>释经判断</b>（与罪民认同及替代意向）；<b>正典成全</b>（惟有基督实际成全赎罪）。不要把第三层倒写成摩西当时已完成的工作。</div>','03 / 原文意向与上下文')
